import sys
import math

def is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    limit = int(math.isqrt(n))
    i = 5
    while i <= limit:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def main():
    data = sys.stdin.read().split()
    if len(data) < 2:
        return
    a, b = map(int, data[:2])
    if a > b:
        a, b = b, a
    primes = [str(num) for num in range(max(a, 2), b + 1) if is_prime(num)]
    sys.stdout.write("\n".join(primes))
    if primes:
        sys.stdout.write("\n")

if __name__ == "__main__":
    main()
